package dev.soundceiling.app;
import android.media.AudioManager;
final class MeasurementVolumeCurve{private final AudioManager audio;private final int min,max;MeasurementVolumeCurve(AudioManager a){audio=a;min=a.getStreamMinVolume(AudioManager.STREAM_MUSIC);max=a.getStreamMaxVolume(AudioManager.STREAM_MUSIC);}int minIndex(){return min;}int maxIndex(){return max;}Snapshot snapshot(int type){float[] raw=new float[max-min+1];for(int i=min;i<=max;i++){try{raw[i-min]=audio.getStreamVolumeDb(AudioManager.STREAM_MUSIC,i,type);}catch(RuntimeException e){raw[i-min]=Float.NaN;}}VolumeCurveMath.ValidationResult r=VolumeCurveMath.validate(raw,min,max);return new Snapshot(raw,r.gains,r.fallbackUsed,r.reason,r.source);}float gainDbForIndex(int index,int type){Snapshot s=snapshot(type);return s.measuredGains[DbMath.clamp(index,min,max)-min];}static final class Snapshot{final float[] rawGains,measuredGains;final boolean fallbackUsed;final String validationReason;final ControlVolumeCurve.Source source;Snapshot(float[] r,float[] m,boolean f,String v,ControlVolumeCurve.Source s){rawGains=r.clone();measuredGains=m.clone();fallbackUsed=f;validationReason=v;source=s;}boolean calibrated(){return source!=ControlVolumeCurve.Source.SYNTHETIC_FALLBACK;}}}
